using Mutagen.Bethesda.Plugins;
using Mutagen.Bethesda.Plugins.Records;
using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// Worldspace FNAM is xEdit's second Flags byte (Player Followers Can't Warp Here, Show Space, Prevent Merge Cell
// Content, Allow ProcGen, Allow Cell Content); it was raw bytes. In Starfield.esm it is 0 on 431 worldspaces, 1 on
// OverlayTraitCharredEcosystemMd02Water (2C7419:Starfield.esm) and 4 on LC030World (260A7C:Starfield.esm).
// HNAM (unknown in xEdit too) is always one byte: 5 on 379 worldspaces, 0 on 54; it becomes a byte.
// Each test reads a whole worldspace from Starfield.esm with both readers and writes it back byte for byte.
public class WorldspaceFlagsTests
{
    // OverlayTraitCharredEcosystemMd02Water (2C7419:Starfield.esm)
    internal const string CharredWater = "";

    // LC030World (260A7C:Starfield.esm), without its FULL (a localized string ID; this test plugin is not localized)
    internal const string Lc030World = "";

    internal static IEnumerable<IWorldspaceGetter> Read(string hex)
        => ReadBoth<IWorldspaceGetter>(Record("WRLD", Hex(hex)), f => Worldspace.CreateFromBinary(f), (s, p) => WorldspaceBinaryOverlay.WorldspaceFactory(s, p));

    internal static void WritesBack(IWorldspaceGetter world, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(w => world.WriteToBinary(w)));
        var original = GameConstants.Starfield.MajorRecord(Record("WRLD", Hex(hex)));
        // Subrecord by subrecord first, so a failure names the subrecord
        var w = written.EnumerateSubrecords().Select(s => $"{s.RecordType} {Convert.ToHexString(s.Content)}").ToList();
        var o = original.EnumerateSubrecords().Select(s => $"{s.RecordType} {Convert.ToHexString(s.Content)}").ToList();
        for (int i = 0; i < Math.Min(w.Count, o.Count); i++) w[i].ShouldBe(o[i], $"subrecord #{i}");
        w.Count.ShouldBe(o.Count);
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    [Fact]
    public void Flags2_PlayerFollowersCannotWarpHere()
    {
        foreach (var world in Read(CharredWater))
        {
            world.Flags2.ShouldBe(Worldspace.Flag2.PlayerFollowersCannotWarpHere);
            world.HNAM.ShouldBe((byte)5);
            WritesBack(world, CharredWater);
        }
    }

    [Fact]
    public void Flags2_PreventMergeCellContent()
    {
        foreach (var world in Read(Lc030World))
        {
            world.Flags2.ShouldBe(Worldspace.Flag2.PreventMergeCellContent);
            world.HNAM.ShouldBe((byte)5);
            WritesBack(world, Lc030World);
        }
    }

    [Fact]
    public void Flags2_Written()
    {
        var world = new Worldspace(new FormKey(TestModKey, 0x800), StarfieldRelease.Starfield)
        {
            Flags2 = Worldspace.Flag2.AllowProcGen | Worldspace.Flag2.ShowSpace,
            HNAM = 5,
        };
        var written = GameConstants.Starfield.MajorRecord(Write(w => world.WriteToBinary(w)));
        written.FindSubrecord(new RecordType("FNAM")).Content.ToArray().ShouldBe(new byte[] { 0x0A });
        written.FindSubrecord(new RecordType("HNAM")).Content.ToArray().ShouldBe(new byte[] { 0x05 });
    }
}
